<hr />
<h2>2. <code>knit_to_latex()</code> only the table as tex</h2>
<p>There is a function <a href="https://rdrr.io/cran/flextable/src/R/printers.R#sym-knit_to_latex" rel="nofollow noreferrer">here</a> called <code>knit_to_latex</code> but it isn't exported. You can rewrite it to directly save the flextable as LaTeX (.tex) file:</p>
<pre><code>library(flextable)


knit_to_latex &lt;- function(x, filename = 'flextable.tex', bookdown = FALSE, quarto = FALSE) {
  align &lt;- x$properties$align
  tabcolsep &lt;- x$properties$opts_pdf$tabcolsep
  ft.arraystretch &lt;- x$properties$opts_pdf$arraystretch
  ft.latex.float &lt;- x$properties$opts_pdf$float

  flextable_global &lt;- flextable:::flextable_global
  fix_border_issues &lt;- flextable:::fix_border_issues
  latex_container_none &lt;- flextable:::latex_container_none
  latex_container_float &lt;- flextable:::latex_container_float
  latex_container_wrap &lt;- flextable:::latex_container_wrap
  latex_container_str &lt;- flextable:::latex_container_str
  caption_bookdown_latex &lt;- flextable:::caption_bookdown_latex
  caption_default_latex &lt;- flextable:::caption_default_latex
  gen_raw_latex &lt;- flextable:::gen_raw_latex
  format_double &lt;- flextable:::format_double
  colcode0 &lt;- flextable:::colcode0

  x &lt;- flextable_global$defaults$post_process_all(x)
  x &lt;- flextable_global$defaults$post_process_pdf(x)
  x &lt;- fix_border_issues(x)

  if (&quot;none&quot; %in% ft.latex.float) {
    lat_container &lt;- latex_container_none()
  } else if (&quot;float&quot; %in% ft.latex.float) {
    lat_container &lt;- latex_container_float()
  } else if (&quot;wrap-l&quot; %in% ft.latex.float) {
    lat_container &lt;- latex_container_wrap(placement = &quot;l&quot;)
  } else if (&quot;wrap-r&quot; %in% ft.latex.float) {
    lat_container &lt;- latex_container_wrap(placement = &quot;r&quot;)
  } else if (&quot;wrap-i&quot; %in% ft.latex.float) {
    lat_container &lt;- latex_container_wrap(placement = &quot;i&quot;)
  } else if (&quot;wrap-o&quot; %in% ft.latex.float) {
    lat_container &lt;- latex_container_wrap(placement = &quot;o&quot;)
  } else {
    lat_container &lt;- latex_container_none()
  }

  tab_props &lt;- knitr::opts_current$get()
  topcaption &lt;- tab_props$topcaption
  if (is.null(topcaption)) topcaption &lt;- TRUE

  if (quarto) {
    caption_str &lt;- &quot;&quot;
  } else if (bookdown) {
    caption_str &lt;- caption_bookdown_latex(x)
  } else {
    caption_str &lt;- caption_default_latex(x)
  }

  container_str &lt;- latex_container_str(
    x = x,
    latex_container = lat_container,
    quarto = quarto
  )

  str &lt;- gen_raw_latex(
    x,
    lat_container = lat_container,
    caption = caption_str,
    topcaption = topcaption,
    quarto = quarto
  )

  latex &lt;- paste(
    container_str[1],
    str,
    container_str[2],
    sep = &quot;\n\n&quot;
  )

  z &lt;- paste(
    &quot;\\global\\setlength{\\Oldarrayrulewidth}{\\arrayrulewidth}&quot;,
    &quot;\\global\\setlength{\\Oldtabcolsep}{\\tabcolsep}&quot;,
    sprintf(&quot;\\setlength{\\tabcolsep}{%spt}&quot;, format_double(x$properties$opts_pdf$tabcolsep, 0)),
    sprintf(&quot;\\renewcommand*{\\arraystretch}{%s}&quot;, format_double(x$properties$opts_pdf$arraystretch, 2)),
    latex,
    sprintf(&quot;\\arrayrulecolor[HTML]{%s}&quot;, colcode0(x$properties$opts_pdf$default_line_color)),
    &quot;\\global\\setlength{\\arrayrulewidth}{\\Oldarrayrulewidth}&quot;,
    &quot;\\global\\setlength{\\tabcolsep}{\\Oldtabcolsep}&quot;,
    &quot;\\renewcommand*{\\arraystretch}{1}&quot;,
    sep = &quot;\n\n&quot;
  )
  writeLines(z, filename)
}

knit_to_latex(flextable(airquality[1:5, ]))
</code></pre>
